import math

def ukuran_perkiraan(ukuran, err, target):
    for i in range(len(ukuran) - 1):
        a, b = err[i], err[i + 1]
        if a >= target >= b and a != b:
            f = (a - target) / (a - b)
            return round(ukuran[i] * (ukuran[i + 1] / ukuran[i]) ** f)
    return None

