from math import comb

def error_voting(p, k):
    batas = k // 2 + 1
    return sum(comb(k, j) * p ** j * (1 - p) ** (k - j) for j in range(batas, k + 1))

for k in [1, 3, 5, 7]:
    print(f"{k} ahli independen dengan error 3 persen: error voting {error_voting(0.03, k):.6f}")

